     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
     4	import { useContentfulEntries } from 'app/hooks/useContentful';
     5	import { CONTENTFUL_FALLBACK_LOCALE } from 'app/config/contentful';
     6	import { ZimmIconAndText } from 'app/components/ui-kits/molecules/zimmIconAndText';
     7	import type { IconAndTextEntry } from 'app/types/contentful';
     8	
     9	const ZIMM_BENEFITS_RECIPE = 'ZimmBenefits';
    10	
    11	/**
    12	 * Zimmermann Benefits section (SFCC-317). Fetches the `iconAndText` Contentful entry and renders
    13	 * it inside a branded background wrapper. Renders nothing if the entry is unpublished or the fetch
    14	 * fails — surrounding layout is unaffected.
    15	 *
    16	 * Provisional placement: Shipping & Returns PDP drawer tab (until cart drawer ships — SFCC-825/277).
    17	 */
    18	export const ZimmBenefits = () => {
    19	  const styles = useMultiStyleConfig(ZIMM_BENEFITS_RECIPE, {});
    20	  // useMultiSite ships untyped from the base SFCC package — same cast pattern as footer/index.tsx.
    21	  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
    22	  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
    23	  // Filter by placement so the correct entry is always selected, regardless of how many
    24	  // iconAndText entries exist in the space. Contentful field filter syntax: fields.<id>=<value>.
    25	  const { data: entries } = useContentfulEntries<IconAndTextEntry>(
    26	    'iconAndText',
    27	    false,
    28	    locale,
    29	    'fields.placement=benefits',
    30	  );
    31	  const entry = entries?.[0] ?? null;
    32	
    33	  if (!entry?.fields.items?.length) return null;
    34	
    35	  // Exclude any item whose linked entry or icon asset was not resolved by include=2.
    36	  // An unresolved link has no `fields` property — reading it would throw at the ZimmIconAndText map.
    37	  const resolvedItems = entry.fields.items.filter(
    38	    (item) => item.fields?.icon?.fields?.file != null && item.fields.heading != null,
    39	  );
    40	
    41	  if (!resolvedItems.length) return null;
    42	
    43	  return (
    44	    <chakra.div __css={styles.root}>
    45	      <ZimmIconAndText
    46	        layout={entry.fields.layout}
    47	        sectionTitle={entry.fields.sectionTitle}
    48	        items={resolvedItems.map((item) => ({
    49	          id: item.sys.id,
    50	          icon: item.fields.icon,
    51	          heading: item.fields.heading,
    52	          description: item.fields.description,
    53	        }))}
    54	      />
    55	    </chakra.div>
    56	  );
    57	};
